// Standalone geodesic hex/pentagon sphere inspector — NOT part of the Memory Planet app.
// Purpose: visually verify the topology (tools/hexsphere-debug.json, generated by
// scripts/generate-hexgrid.js) independent of any game rendering, assets, or gameplay.
// No terrain, no buildings, no Kenney assets here on purpose.
(function () {
  var RADIUS = 5;
  var GAP_AMOUNT = 0.10; // fraction each corner shrinks toward its tile's own center, for a visible gap
  var PENTAGON_COLOR = new THREE.Color(0xff6b4a);
  var HEXAGON_COLOR = new THREE.Color(0x6fb3c9);
  var HIGHLIGHT_COLOR = new THREE.Color(0xffe66b);

  var canvas = document.getElementById('scene-canvas');
  var hud = document.getElementById('hud');

  function normalize(v) {
    var len = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
    return [v[0] / len, v[1] / len, v[2] / len];
  }
  function lerp3(a, b, t) {
    return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
  }

  var renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
  renderer.setPixelRatio(window.devicePixelRatio || 1);
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.outputEncoding = THREE.sRGBEncoding;

  var scene = new THREE.Scene();
  scene.background = new THREE.Color(0x10151c);

  var camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 200);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x333844, 1.2));
  var sun = new THREE.DirectionalLight(0xffffff, 0.6);
  sun.position.set(6, 10, 8);
  scene.add(sun);

  window.addEventListener('resize', function () {
    renderer.setSize(window.innerWidth, window.innerHeight);
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
  });

  // --- Minimal orbit camera (drag to rotate, wheel to zoom) — no external OrbitControls dep ---
  var camTheta = 0.7, camPhi = 1.1, camDistance = 14;
  var MIN_DIST = 6.5, MAX_DIST = 40;
  function updateCamera() {
    camera.position.set(
      camDistance * Math.sin(camPhi) * Math.sin(camTheta),
      camDistance * Math.cos(camPhi),
      camDistance * Math.sin(camPhi) * Math.cos(camTheta)
    );
    camera.lookAt(0, 0, 0);
  }
  updateCamera();

  var dragging = false, dragMoved = false, lastX = 0, lastY = 0;
  canvas.addEventListener('mousedown', function (e) {
    dragging = true; dragMoved = false; lastX = e.clientX; lastY = e.clientY;
    canvas.classList.add('dragging');
  });
  window.addEventListener('mouseup', function () { dragging = false; canvas.classList.remove('dragging'); });
  window.addEventListener('mousemove', function (e) {
    if (dragging) {
      var dx = e.clientX - lastX, dy = e.clientY - lastY;
      if (Math.abs(dx) + Math.abs(dy) > 3) dragMoved = true;
      camTheta -= dx * 0.006;
      camPhi -= dy * 0.006;
      camPhi = Math.max(0.15, Math.min(Math.PI - 0.15, camPhi));
      lastX = e.clientX; lastY = e.clientY;
      updateCamera();
    } else {
      handleHover(e);
    }
  });
  canvas.addEventListener('wheel', function (e) {
    e.preventDefault();
    camDistance *= (1 + e.deltaY * 0.001);
    camDistance = Math.max(MIN_DIST, Math.min(MAX_DIST, camDistance));
    updateCamera();
  }, { passive: false });
  canvas.addEventListener('click', function (e) {
    if (!dragMoved) handleSelect(e);
  });

  // --- Load precomputed topology and build one merged, gapped BufferGeometry ---
  var raycaster = new THREE.Raycaster();
  var pointer = new THREE.Vector2();
  var mesh, faceToTileId, tileVertexRange, baseColors, tiles;
  var hoveredId = null, selectedId = null;

  fetch('hexsphere-debug.json')
    .then(function (res) { return res.json(); })
    .then(function (grid) {
      tiles = grid.tiles;
      var totalTriangles = tiles.reduce(function (sum, t) { return sum + t.sides; }, 0);
      var positions = new Float32Array(totalTriangles * 3 * 3);
      var colors = new Float32Array(totalTriangles * 3 * 3);
      faceToTileId = new Int32Array(totalTriangles);
      tileVertexRange = {};

      var vCursor = 0, triCursor = 0;
      tiles.forEach(function (tile) {
        var center = tile.dir.map(function (c) { return c * RADIUS; });
        var color = tile.sides === 5 ? PENTAGON_COLOR : HEXAGON_COLOR;
        var startVert = vCursor;
        for (var k = 0; k < tile.sides; k++) {
          var c0 = normalize(lerp3(tile.corners[k], tile.dir, GAP_AMOUNT));
          var c1 = normalize(lerp3(tile.corners[(k + 1) % tile.sides], tile.dir, GAP_AMOUNT));
          var p0 = c0.map(function (c) { return c * RADIUS; });
          var p1 = c1.map(function (c) { return c * RADIUS; });
          var tri = [center, p0, p1];
          for (var v = 0; v < 3; v++) {
            positions[vCursor * 3] = tri[v][0];
            positions[vCursor * 3 + 1] = tri[v][1];
            positions[vCursor * 3 + 2] = tri[v][2];
            colors[vCursor * 3] = color.r;
            colors[vCursor * 3 + 1] = color.g;
            colors[vCursor * 3 + 2] = color.b;
            vCursor++;
          }
          faceToTileId[triCursor] = tile.id;
          triCursor++;
        }
        tileVertexRange[tile.id] = [startVert, vCursor - startVert];
      });

      baseColors = colors.slice();
      var geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
      geometry.computeVertexNormals();
      var material = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.8 });
      mesh = new THREE.Mesh(geometry, material);
      scene.add(mesh);

      var pentagonCount = tiles.filter(function (t) { return t.sides === 5; }).length;
      var hexagonCount = tiles.filter(function (t) { return t.sides === 6; }).length;
      console.log('[hexsphere-inspector] frequency:', grid.frequency);
      console.log('[hexsphere-inspector] tiles:', tiles.length, 'pentagons:', pentagonCount, 'hexagons:', hexagonCount);
      console.log('[hexsphere-inspector] triangles rendered:', totalTriangles);
      hud.textContent = 'Loaded ' + tiles.length + ' tiles (' + pentagonCount + ' pentagons, ' + hexagonCount + ' hexagons). Hover or click a tile.';

      (function loop() {
        requestAnimationFrame(loop);
        renderer.render(scene, camera);
      })();
    });

  function pickTileId(e) {
    if (!mesh) return null;
    var rect = canvas.getBoundingClientRect();
    pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);
    var hits = raycaster.intersectObject(mesh);
    if (!hits.length) return null;
    return faceToTileId[hits[0].faceIndex];
  }

  function setTileColor(tileId, color) {
    var range = tileVertexRange[tileId];
    var colorAttr = mesh.geometry.attributes.color;
    for (var i = 0; i < range[1]; i++) {
      colorAttr.array[(range[0] + i) * 3] = color.r;
      colorAttr.array[(range[0] + i) * 3 + 1] = color.g;
      colorAttr.array[(range[0] + i) * 3 + 2] = color.b;
    }
    colorAttr.needsUpdate = true;
  }
  function restoreTileColor(tileId) {
    var range = tileVertexRange[tileId];
    var colorAttr = mesh.geometry.attributes.color;
    for (var i = 0; i < range[1] * 3; i++) {
      colorAttr.array[range[0] * 3 + i] = baseColors[range[0] * 3 + i];
    }
    colorAttr.needsUpdate = true;
  }

  function describeTile(tileId) {
    var t = tiles[tileId];
    var lat = (Math.asin(t.dir[1]) * 180 / Math.PI).toFixed(1);
    var lon = (Math.atan2(t.dir[2], t.dir[0]) * 180 / Math.PI).toFixed(1);
    return '<b>Tile ' + t.id + '</b><br>' +
      'Type: ' + (t.sides === 5 ? 'pentagon' : 'hexagon') + '<br>' +
      'Neighbors: ' + t.sides + '<br>' +
      'Lat/Lon: ' + lat + '&deg;, ' + lon + '&deg;';
  }

  function handleHover(e) {
    if (!mesh) return;
    var id = pickTileId(e);
    if (id === hoveredId) return;
    if (hoveredId !== null && hoveredId !== selectedId) restoreTileColor(hoveredId);
    hoveredId = id;
    if (hoveredId !== null && hoveredId !== selectedId) setTileColor(hoveredId, HIGHLIGHT_COLOR);
    if (selectedId === null) hud.innerHTML = hoveredId !== null ? describeTile(hoveredId) : 'Hover or click a tile.';
  }

  function handleSelect(e) {
    if (!mesh) return;
    var id = pickTileId(e);
    if (selectedId !== null) restoreTileColor(selectedId);
    selectedId = id;
    if (selectedId !== null) {
      setTileColor(selectedId, HIGHLIGHT_COLOR);
      hud.innerHTML = describeTile(selectedId) + '<br><i>(selected)</i>';
    } else {
      hud.textContent = 'Hover or click a tile.';
    }
  }
})();
